+func TestParsingIndexSteppedRangeExpressions(t *testing.T) {
+	tests := []struct {
+		input    string
+		expected string
+	}{
+		{"myArray[99:101:2]", "(myArray[99:101:2])"},
+		{"myArray[99 : 101 : 2]", "(myArray[99:101:2])"},
+		{"myArray[::2]", "(myArray[::2])"},
+		{"myArray[4::-1]", "(myArray[4::(-1)])"},
+		{"myArray[:5:2]", "(myArray[:5:2])"},
+		{"myArray[1::2]", "(myArray[1::2])"},
+		{"myArray[8:1:-2]", "(myArray[8:1:(-2)])"},
+		{"myArray[1:2:3:4]", ""},
+	}
+
+	for _, tt := range tests {
+		l := lexer.New(tt.input)
+		p := New(l)
+		program := p.ParseProgram()
+
+		if tt.expected == "" {
+			if len(p.Errors()) == 0 {
+				t.Errorf("expected parser errors for %q", tt.input)
+			}
+			continue
+		}
+
+		checkParserErrors(t, p)
+		if program.String() != tt.expected {
+			t.Errorf("program.String() wrong. input=%q got=%q want=%q", tt.input, program.String(), tt.expected)
+		}
+	}
+}
